package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"strings"
	"sync"
)

type User struct {
	Username string
	Role     string
	APIKey   string
}

type Document struct {
	ID      string
	Owner   string
	Content string
	Secret  bool
}

var (
	users     = map[string]*User{}
	documents = map[string]*Document{}
	mu        sync.RWMutex
)

func init() {
	users["ak_admin_001"] = &User{Username: "admin", Role: "admin", APIKey: "ak_admin_001"}
	users["ak_user_002"] = &User{Username: "alice", Role: "user", APIKey: "ak_user_002"}
	documents["doc1"] = &Document{ID: "doc1", Owner: "admin", Content: "Top Secret Plan", Secret: true}
	documents["doc2"] = &Document{ID: "doc2", Owner: "alice", Content: "Public Notes", Secret: false}
}

func generateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

// authenticateRequest validates the API key and returns the user
func authenticateRequest(r *http.Request) *User {
	apiKey := r.Header.Get("X-API-Key")
	if apiKey == "" {
		return nil
	}
	mu.RLock()
	defer mu.RUnlock()
	return users[apiKey]
}

// authorizePath checks if the user's role permits access to the given path.
// Admin paths require admin role. This is the FIRST line of defense.
func authorizePath(user *User, path string) bool {
	// Protect admin endpoints
	if strings.HasPrefix(path, "/admin/") {
		return user.Role == "admin"
	}
	// Protect internal API endpoints
	if strings.HasPrefix(path, "/internal/") {
		return user.Role == "admin"
	}
	return true
}

// securityMiddleware performs authentication and path-based authorization
func securityMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		user := authenticateRequest(r)
		if user == nil {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}

		// Path-based authorization check on the raw request path
		// We use r.URL.Path which is already decoded once by net/http
		if !authorizePath(user, r.URL.Path) {
			http.Error(w, "Forbidden", http.StatusForbidden)
			return
		}

		// Store user in context via header rewriting (simplified)
		r.Header.Set("X-Verified-User", user.Username)
		r.Header.Set("X-Verified-Role", user.Role)
		next.ServeHTTP(w, r)
	})
}

// normalizePath decodes any remaining percent-encoding for clean routing
// This handles cases where clients double-encode URLs
func normalizePath(path string) string {
	decoded, err := url.PathUnescape(path)
	if err != nil {
		return path
	}
	return decoded
}

// router dispatches requests based on normalized path
func router(w http.ResponseWriter, r *http.Request) {
	// Normalize the path for consistent routing
	normalizedPath := normalizePath(r.URL.Path)

	switch {
	case strings.HasPrefix(normalizedPath, "/admin/documents/delete/"):
		handleAdminDelete(w, r, normalizedPath)
	case strings.HasPrefix(normalizedPath, "/admin/documents/list"):
		handleAdminList(w, r)
	case strings.HasPrefix(normalizedPath, "/internal/secrets"):
		handleInternalSecrets(w, r)
	case strings.HasPrefix(normalizedPath, "/documents/"):
		handleGetDocument(w, r, normalizedPath)
	case normalizedPath == "/documents" && r.Method == "POST":
		handleCreateDocument(w, r)
	default:
		http.NotFound(w, r)
	}
}

func handleAdminDelete(w http.ResponseWriter, r *http.Request, path string) {
	docID := strings.TrimPrefix(path, "/admin/documents/delete/")
	if docID == "" {
		http.Error(w, "Missing document ID", http.StatusBadRequest)
		return
	}
	mu.Lock()
	defer mu.Unlock()
	if _, exists := documents[docID]; !exists {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	delete(documents, docID)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Deleted %s", docID)
}

func handleAdminList(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()
	var result []string
	for id, doc := range documents {
		result = append(result, fmt.Sprintf("%s (owner=%s, secret=%v)", id, doc.Owner, doc.Secret))
	}
	fmt.Fprintf(w, "Documents:\n%s", strings.Join(result, "\n"))
}

func handleInternalSecrets(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()
	var result []string
	for id, doc := range documents {
		if doc.Secret {
			result = append(result, fmt.Sprintf("%s: %s", id, doc.Content))
		}
	}
	fmt.Fprintf(w, "Secrets:\n%s", strings.Join(result, "\n"))
}

func handleGetDocument(w http.ResponseWriter, r *http.Request, path string) {
	docID := strings.TrimPrefix(path, "/documents/")
	mu.RLock()
	defer mu.RUnlock()
	doc, exists := documents[docID]
	if !exists {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	user := r.Header.Get("X-Verified-User")
	if doc.Secret && doc.Owner != user {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}
	fmt.Fprintf(w, "Document %s: %s", doc.ID, doc.Content)
}

func handleCreateDocument(w http.ResponseWriter, r *http.Request) {
	content := r.FormValue("content")
	secret := r.FormValue("secret") == "true"
	user := r.Header.Get("X-Verified-User")

	doc := &Document{
		ID:      generateID(),
		Owner:   user,
		Content: content,
		Secret:  secret,
	}
	mu.Lock()
	documents[doc.ID] = doc
	mu.Unlock()
	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "Created %s", doc.ID)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/", router)

	server := &http.Server{
		Addr:    ":8080",
		Handler: securityMiddleware(mux),
	}
	server.ListenAndServe()
}
